/** Explicit small native-server acceptance fixture. Never enabled or reset at startup. */
public final class CityWorksLab {
 public static final class Run {public boolean postRunning,postDone;public int postPhase;public long postStarted,postFood,postBread,postDirect,postWheat,postMoney;public String postFailure="";public Map<String,Boolean> postChecks=new LinkedHashMap<>();public boolean running,done;public int phase;public long startedGame,startedSim,phaseSim,initialMoney,migrationStart;public String failure="";public Map<String,Boolean> checks=new LinkedHashMap<>();public List<UUID> originals=new ArrayList<>();public List<Map<String,Object>> samples=new ArrayList<>();}
 static final String NAME="城市维护094专用验证";
 static UUID create(ServerPlayer player){var s=player.server;var data=CityData.get(s);var existing=data.cities().stream().filter(c->c.name.equals(NAME)).findFirst();if(existing.isPresent())return existing.get().id;var level=player.serverLevel();var min=new BlockPos(8000,-61,8000);var bounds=CityBounds.between(min,min.offset(31,11,31));for(int x=8000>>4;x<=8031>>4;x++)for(int z=8000>>4;z<=8031>>4;z++)CityEconomy.require(level.hasChunk(x,z),"先靠近8016 -60 8016加载验证区，不强制加载");for(var c:data.cities())CityEconomy.require(!c.dimension.equals(level.dimension().location().toString())||!c.bounds.intersects(bounds),"验证区被其他城市占用，停止创建");for(int i=0;i<bounds.volume();i++){var p=bounds.at(i);if(p.getY()>-61)CityEconomy.require(level.getBlockState(p).isAir(),"验证区已有内容，不覆盖");}
  var c=data.create(player.getUUID(),NAME,level.dimension().location().toString(),bounds);var d=RuralSettlement.get(s);for(int x=0;x<32;x++)for(int z=0;z<32;z++)level.setBlock(min.offset(x,0,z),Blocks.STONE.defaultBlockState(),2);
  var type=BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse("customnpcs:customnpc"));CityEconomy.require(type!=null,"联合服需要CustomNPCs");
  for(int n=0;n<3;n++){int bx=n==0?2:n==1?11:22;var entity=type.create(level);CityEconomy.require(entity instanceof Mob,"原生NPC创建失败");entity.moveTo(min.getX()+bx+1.5,-60,min.getZ()+10.5,0,0);entity.setCustomName(Component.literal(n<2?"验证工匠"+(n+1):"验证农夫"));((Mob)entity).setNoAi(true);((Mob)entity).setPersistenceRequired();level.addFreshEntity(entity);c.residents.add(entity.getUUID());var person=d.enroll(s,c,entity.getUUID(),entity.getName().getString());person.trainedHours=9;
   long sitePos;if(n<2){var origin=min.offset(bx,0,2);var hb=CityBounds.between(origin,origin.offset(4,4,4));UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,"验证工坊"+(n+1),"工坊",hb));var h=CityHousing.house(c,id);h.configured=true;h.personal=false;h.workerLimit=1;for(int x=0;x<5;x++)for(int y=0;y<5;y++)for(int z=0;z<5;z++){boolean solid=y==0||y==4||x==0||x==4||z==0||z==4;if(x==2&&z==0&&(y==1||y==2))solid=false;if(solid)level.setBlock(origin.offset(x,y,z),y==0?Blocks.STONE_BRICKS.defaultBlockState():Blocks.OAK_PLANKS.defaultBlockState(),2);}var bench=origin.offset(2,1,2);level.setBlock(bench,Blocks.CRAFTING_TABLE.defaultBlockState(),2);for(int i=0;i<hb.volume();i++){var p=hb.at(i);if(!level.getBlockState(p).isAir())h.baseline.put(p.asLong(),CityMaintenance.encode(level.getBlockState(p)));}RuralSuccession.employ(s,c,person.id,id);person.trainedHours=9;sitePos=bench.asLong();
   }else{var work=min.offset(bx,1,3);level.setBlock(work,RuralBlocks.SIFTER.get().defaultBlockState(),3);RuralTools.register(level,work,(RuralBlocks.Link)level.getBlockEntity(work));var site=d.state.sites.get(RuralSettlement.key(c.id,work.asLong()));site.worker=person.id;person.role=RuralRules.Role.FARMER;sitePos=work.asLong();for(int x=0;x<5;x++)for(int z=0;z<4;z++){var field=min.offset(bx+x,0,5+z);level.setBlock(field,Blocks.FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,7),2);level.setBlock(field.above(),Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),2);}}
   for(int box=0;box<3;box++){var pos=min.offset(bx+box,1,12);level.setBlock(pos,RuralBlocks.CHEST.get().defaultBlockState(),3);var link=(RuralBlocks.Link)level.getBlockEntity(pos);link.offset=BlockPos.of(sitePos).subtract(pos);link.setChanged();RuralTools.register(level,pos,link);var stock=d.state.boxes.get(RuralSettlement.key(c.id,pos.asLong())).stock;stock.family=person.family;stock.bread=10;}
  }
  var warehousePos=min.offset(17,1,14);level.setBlock(warehousePos,Blocks.CHEST.defaultBlockState(),3);var storage=(net.minecraft.world.Container)level.getBlockEntity(warehousePos);storage.setItem(0,new ItemStack(Items.CRAFTING_TABLE,2));storage.setItem(1,new ItemStack(Items.BREAD,64));UUID warehouse=UUID.randomUUID();c.warehouses.put(warehouse,new CityRegistry.Warehouse(warehouse,"真实应急公仓",warehousePos));var economy=CityEconomy.get(s);economy.state.accounts.put(CityEconomy.treasury(c.id),500L);economy.state.warehouseOwners.put(warehouse,CityEconomy.treasury(c.id));economy.log(s.overworld().getGameTime(),"LAB_INITIAL","outside_lab",CityEconomy.treasury(c.id),500,"一次性验证区初始资金，正式基线前");c.works.resources.put("minecraft:oak_planks",512);c.works.resources.put("minecraft:stone_bricks",256);c.works.resources.put("minecraft:bread",16);var bread=new CityHousing.Material();bread.stock=100;bread.priceCents=600;bread.supply=0;c.housing.market.put("minecraft:bread",bread);c.works.day=0;d.enable(s,c);CityWorks.beginFinalize(s,c);data.setDirty();d.setDirty();economy.setDirty();return c.id;
 }
 static long money(MinecraftServer s,CityData.City c){var accounts=CityEconomy.get(s).state.accounts;long n=accounts.getOrDefault(CityEconomy.treasury(c.id),0L)+accounts.getOrDefault("market:"+c.id,0L);for(UUID id:c.residents)n+=accounts.getOrDefault(CityEconomy.person(id),0L)+accounts.getOrDefault("works:"+c.id+":"+id,0L);return n;}
 static void start(MinecraftServer s,CityData.City c){CityEconomy.require(c.name.equals(NAME)&&c.works.finalized,"只在已定稿专用验证区运行");CityEconomy.require(!c.works.lab.running&&!c.works.lab.done,"该验证已启动或完成，不自动重置");var r=c.works.lab;r.running=true;r.startedGame=s.overworld().getGameTime();r.startedSim=c.works.clock;r.phaseSim=c.works.clock;r.initialMoney=money(s,c);r.migrationStart=c.works.migrantSilver;r.originals=new ArrayList<>(c.residents);c.works.nextMeal=c.works.clock+1200;c.works.nextSegment=c.works.clock+3000;for(var id:r.originals){var person=RuralSettlement.get(s).state.people.get(id);if(person.role==RuralRules.Role.ARTISAN)person.nourishment=11;}for(var e:c.housing.houses.entrySet())if(CityWorks.workshop(c,e.getKey()))for(long p:e.getValue().baseline.keySet()){CityWorks.destroyInventory(s,c,p);e.getValue().damaged.add(p);CityWorks.schedule(c,p,Blocks.AIR.defaultBlockState(),CityMaintenance.decode(e.getValue().baseline.get(p)),"LAB_ATTACK");}c.works.emergency=true;CityData.get(s).setDirty();write(s,c);}
 static void sample(MinecraftServer s,CityData.City c){var r=c.works.lab;Map<String,Object> row=new LinkedHashMap<>();row.put("gameTick",s.overworld().getGameTime());row.put("simulationClock",c.works.clock);row.put("phase",r.phase);row.put("money",money(s,c));row.put("expectedMoney",r.initialMoney+c.works.migrantSilver-r.migrationStart);row.put("health",c.housing.houses.values().stream().mapToLong(CityWorks::health).sum());row.put("pending",c.works.pending.size());row.put("emergency",c.works.emergency);row.put("wages",c.works.wages);row.put("publicMeals",c.works.emergencyMeals);row.put("repaired",c.works.repaired);row.put("successions",c.works.successions);r.samples.add(row);if(r.samples.size()>256)r.samples.removeFirst();}
 static void write(MinecraftServer s,CityData.City c){try{Path file=s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/native-094.json");Files.createDirectories(file.getParent());var report=new LinkedHashMap<String,Object>();report.put("version","0.9.4");report.put("timestamp",java.time.OffsetDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).toString());report.put("city",c.id);report.put("run",c.works.lab);report.put("materialsConsumed",c.works.materialsConsumed);report.put("materialsRecovered",c.works.recovered);report.put("publicRemaining",c.works.resources);report.put("originalsStillDead",c.works.lab.originals.stream().allMatch(id->{var p=RuralSettlement.get(s).state.people.get(id);return p!=null&&p.dead;}));Files.writeString(file,CityEconomy.JSON.toJson(report));}catch(Exception ex){org.slf4j.LoggerFactory.getLogger("CityWorksLab").warn("原生验收报告写入失败",ex);}}
 static long grain(MinecraftServer s,CityData.City c){var d=RuralSettlement.get(s);long total=d.state.boxes.values().stream().filter(b->b.city.equals(c.id)&&b.present).mapToLong(b->b.stock.wheat+b.stock.bread).sum();for(String id:List.of("minecraft:wheat","minecraft:bread")){total+=c.works.resources.getOrDefault(id,0);var m=c.housing.market.get(id);if(m!=null)total+=m.stock;for(var house:c.housing.houses.values())total+=house.materials.getOrDefault(id,0);}for(var w:c.warehouses.values())if(!d.state.boxes.containsKey(RuralSettlement.key(c.id,w.pos().asLong())))try{var goods=CityEconomy.get(s).inventory(s,c.id,w.id());total+=goods.getOrDefault("minecraft:bread",0)+goods.getOrDefault("minecraft:wheat",0);}catch(IllegalArgumentException ignored){}return total;}
 static void postStart(MinecraftServer s,CityData.City c){var r=c.works.lab;CityEconomy.require(c.name.equals(NAME)&&r.done&&!r.postRunning&&!r.postDone,"仅完成主验收的专用区可追加一次");var d=RuralSettlement.get(s);CityEconomy.require(!d.state.enabled.contains(c.id),"先保持独立工匠进餐模式");r.postRunning=true;r.postStarted=c.works.clock;r.postFood=grain(s,c);r.postBread=d.audit(c.id).breadEaten;r.postDirect=c.works.materialsConsumed.getOrDefault("minecraft:bread",0L);r.postWheat=d.audit(c.id).wheatHarvested;r.postMoney=money(s,c);c.works.enabled=true;CityData.get(s).setDirty();postWrite(s,c);}
 static void postWrite(MinecraftServer s,CityData.City c){try{var d=RuralSettlement.get(s);var r=c.works.lab;var result=new LinkedHashMap<String,Object>();result.put("timestamp",java.time.OffsetDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).toString());result.put("city",c.id);result.put("running",r.postRunning);result.put("done",r.postDone);result.put("phase",r.postPhase);result.put("failure",r.postFailure);result.put("checks",r.postChecks);result.put("initialGrain",r.postFood);result.put("currentGrain",grain(s,c));result.put("harvested",d.audit(c.id).wheatHarvested-r.postWheat);result.put("privateBreadEaten",d.audit(c.id).breadEaten-r.postBread);result.put("directBreadServed",c.works.materialsConsumed.getOrDefault("minecraft:bread",0L)-r.postDirect);result.put("money",money(s,c));result.put("initialMoney",r.postMoney);Path file=s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/native-post-094.json");Files.createDirectories(file.getParent());Files.writeString(file,CityEconomy.JSON.toJson(result));}catch(Exception ex){org.slf4j.LoggerFactory.getLogger("CityWorksLab").warn("追加验收写入失败",ex);}}
 static void postTick(MinecraftServer s,CityData.City c){var r=c.works.lab;if(!r.postRunning)return;var d=RuralSettlement.get(s);long expected=r.postFood+d.audit(c.id).wheatHarvested-r.postWheat-(d.audit(c.id).breadEaten-r.postBread)-(c.works.materialsConsumed.getOrDefault("minecraft:bread",0L)-r.postDirect);if(grain(s,c)!=expected||money(s,c)!=r.postMoney){r.postFailure="追加运转物资或资金对账失败";r.postRunning=false;c.works.enabled=false;d.state.enabled.remove(c.id);postWrite(s,c);return;}if(r.postPhase==0&&d.audit(c.id).breadEaten>r.postBread){r.postChecks.put("standaloneArtisanConsumptionAudited",true);r.postChecks.put("independentPhaseFoodAndMoneyConserved",true);r.postPhase=1;d.enable(s,c);postWrite(s,c);}if(r.postPhase==1&&d.audit(c.id).wheatHarvested>r.postWheat){r.postChecks.put("successorFarmerActuallyHarvested",true);r.postChecks.put("ruralAndCityPhaseFoodAndMoneyConserved",true);r.postDone=true;r.postRunning=false;c.works.enabled=false;d.state.enabled.remove(c.id);postWrite(s,c);}if(c.works.clock-r.postStarted>144000){r.postFailure="追加测试两模拟小时超时";r.postRunning=false;c.works.enabled=false;d.state.enabled.remove(c.id);postWrite(s,c);}if(s.getTickCount()%600==0)postWrite(s,c);d.setDirty();CityData.get(s).setDirty();}
 static void tick(MinecraftServer s){if(s.getTickCount()%20!=0)return;for(var c:CityData.get(s).cities()){postTick(s,c);var r=c.works.lab;if(!r.running)continue;long now=c.works.clock;if(money(s,c)!=r.initialMoney+c.works.migrantSilver-r.migrationStart){r.failure="资金守恒失败";r.running=false;sample(s,c);write(s,c);continue;}
   if(r.phase==0&&c.housing.houses.values().stream().allMatch(h->h.damaged.isEmpty())&&c.works.pending.isEmpty()&&c.works.emergencyMeals>0){r.checks.put("allDestroyedWorkshopsRebuilt",true);r.checks.put("realPublicMealsConsumed",true);r.checks.put("moneyConservedDuringRecovery",true);r.checks.put("realPublicWorkbenchItemsConsumed",c.works.materialsConsumed.getOrDefault("minecraft:crafting_table",0L)==2);r.checks.put("physicalWorkbenchesRestored",c.buildings.values().stream().filter(b->b.type().equals("工坊")).allMatch(b->CityHousing.house(c,b.id()).baseline.entrySet().stream().filter(e->CityMaintenance.decode(e.getValue()).is(Blocks.CRAFTING_TABLE)).allMatch(e->CityEconomy.level(s,c).hasChunkAt(BlockPos.of(e.getKey()))&&CityEconomy.level(s,c).getBlockState(BlockPos.of(e.getKey())).is(Blocks.CRAFTING_TABLE))));
    var d=RuralSettlement.get(s);for(UUID id:r.originals){var entity=CityEconomy.level(s,c).getEntity(id);if(entity instanceof LivingEntity living)living.hurt(living.damageSources().starve(),Float.MAX_VALUE);if(!d.state.people.get(id).dead){r.failure="测试NPC未发生实际死亡";r.running=false;break;}}r.phase=1;r.phaseSim=now;sample(s,c);write(s,c);
   }else if(r.phase==1&&c.works.successions>=3){var d=RuralSettlement.get(s);r.checks.put("farmerAndArtisansSucceeded",true);r.checks.put("deadOriginalsNotResurrected",r.originals.stream().allMatch(id->d.state.people.get(id).dead&&(!(CityEconomy.level(s,c).getEntity(id) instanceof LivingEntity living)||!living.isAlive())));r.checks.put("newMigrantSavingsAudited",c.works.migrantSilver-r.migrationStart==150);r.checks.put("moneyConservedWithMigration",money(s,c)==r.initialMoney+150);r.phase=2;r.phaseSim=now;sample(s,c);write(s,c);
   }else if(r.phase==2&&now-r.phaseSim>=72000){r.checks.put("continuedWithoutFurtherDeath",RuralSettlement.get(s).state.people.values().stream().filter(p->!r.originals.contains(p.id)&&RuralSettlement.get(s).state.families.get(p.family).city.equals(c.id)).noneMatch(p->p.dead));r.done=r.checks.values().stream().allMatch(Boolean::booleanValue);r.running=false;c.works.enabled=false;RuralSettlement.get(s).state.enabled.remove(c.id);RuralSettlement.get(s).setDirty();if(!r.done)r.failure="至少一项实际验收未通过";sample(s,c);write(s,c);}
   if(s.getTickCount()%600==0){sample(s,c);write(s,c);}if(now-r.startedSim>720000){r.failure="原生验收超过10模拟小时仍未完成";r.running=false;sample(s,c);write(s,c);}CityData.get(s).setDirty();}
 }
}
